from typing import List, Optional
from itertools import permutations


def _inversion_count(perm):
    inv = 0
    n = len(perm)
    for i in range(n):
        for j in range(i + 1, n):
            if perm[i] > perm[j]:
                inv += 1
    return inv


def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    best = None

    row_perms = list(permutations(range(H)))
    col_perms = list(permutations(range(W)))
    row_cost = {p: _inversion_count(p) for p in row_perms}
    col_cost = {p: _inversion_count(p) for p in col_perms}

    for rows in row_perms:
        rc = row_cost[rows]
        if best is not None and rc >= best:
            continue

        for cols in col_perms:
            cc = col_cost[cols]
            if best is not None and rc + cc >= best:
                continue

            ok = True
            for i in range(H):
                row_a = A[rows[i]]
                row_b = B[i]
                for j in range(W):
                    if row_a[cols[j]] != row_b[j]:
                        ok = False
                        break
                if not ok:
                    break

            if ok:
                total = rc + cc
                if best is None or total < best:
                    best = total
                    if best == 0:
                        return 0

    return best
