def count_good_strings(n: int, k: int, s: str) -> int:
    dp = {(): 1}

    for i in range(n):
        ch = s[i]
        ndp = {}

        if ch == '?':
            choices = (0, 1)
        else:
            choices = (0,) if ch == 'A' else (1,)

        for state, ways in dp.items():
            for bit in choices:
                nxt = state + (bit,)

                if len(nxt) == k:
                    if nxt == nxt[::-1]:
                        continue
                    nxt = nxt[1:]

                ndp[nxt] = (ndp.get(nxt, 0) + ways) % MOD

        dp = ndp
        if not dp:
            return 0

    return sum(dp.values()) % MOD
