from typing import List


def _add_element(dp, x: int, k: int) -> None:
    # Process counts in reverse so the current element is used at most once.
    for c in range(k - 1, -1, -1):
        cur = dp[c]
        if not cur:
            continue
        nxt = dp[c + 1]
        for mask in cur:
            nxt.add(mask | x)


def max_subsequence_value(nums: List[int], k: int) -> int:
    n = len(nums)

    # pref[i]: ORs achievable by choosing exactly k elements from nums[:i + 1]
    pref = [None] * n
    dp = [set() for _ in range(k + 1)]
    dp[0].add(0)

    for i, x in enumerate(nums):
        _add_element(dp, x, k)
        if i + 1 >= k:
            pref[i] = dp[k].copy()

    # suff[i]: ORs achievable by choosing exactly k elements from nums[i:]
    suff = [None] * (n + 1)
    dp = [set() for _ in range(k + 1)]
    dp[0].add(0)

    for i in range(n - 1, -1, -1):
        _add_element(dp, nums[i], k)
        if n - i >= k:
            suff[i] = dp[k].copy()

    ans = 0

    # split is the boundary index: first k chosen from nums[:split + 1],
    # last k chosen from nums[split + 1:].
    for split in range(k - 1, n - k):
        left_masks = pref[split]
        right_masks = suff[split + 1]
        if left_masks is None or right_masks is None:
            continue

        for a in left_masks:
            for b in right_masks:
                val = a ^ b
                if val > ans:
                    ans = val

    return ans
