from typing import List


def max_kagamimochi(n: int, sizes: List[int]) -> int:
    low, high = 0, n // 2

    while low < high:
        k = (low + high + 1) // 2

        ok = True
        for i in range(k):
            if sizes[i] * 2 > sizes[n - k + i]:
                ok = False
                break

        if ok:
            low = k
        else:
            high = k - 1

    return low
