def _comb(n: int, r: int) -> int:
    if r < 0 or r > n:
        return 0
    r = min(r, n - r)
    result = 1
    for i in range(1, r + 1):
        result = result * (n - r + i) // i
    return result


def count_ways_to_stair(k: int) -> int:
    ways = 0
    n = 0

    while True:
        down = (1 << n) - k

        # If required down moves already exceed the maximum possible
        # non-consecutive down moves, later n will only be worse.
        if down > n + 1:
            break

        if down >= 0:
            ways += _comb(n + 1, down)

        n += 1

    return ways
